DELIMITER $$
CREATE PROCEDURE cursor_approved_count(OUT p_count INT) SQL SECURITY INVOKER
BEGIN
 DECLARE done BOOL DEFAULT FALSE;
 DECLARE v_id INT;
 DECLARE c CURSOR FOR SELECT request_id FROM cursor_requests WHERE status='approved' ORDER BY request_id;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=TRUE;
 SET p_count=0;
 OPEN c;
 read_loop: LOOP
  FETCH c INTO v_id;
  IF done THEN LEAVE read_loop; END IF;
  SET p_count=p_count+1;
 END LOOP;
 CLOSE c;
END$$
DELIMITER ;
CALL cursor_approved_count(@row_count);
SELECT @row_count AS approved_count;

DELIMITER $$
CREATE PROCEDURE cursor_capped_total(IN p_cap INT,OUT p_total INT) SQL SECURITY INVOKER
BEGIN
 DECLARE done BOOL DEFAULT FALSE;
 DECLARE v_amount INT;
 DECLARE c CURSOR FOR SELECT amount FROM cursor_requests WHERE status='approved' AND amount IS NOT NULL AND amount>=0 ORDER BY request_id;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=TRUE;
 SET p_total=0;
 OPEN c;
 read_loop: LOOP
  FETCH c INTO v_amount;
  IF done THEN LEAVE read_loop; END IF;
  SET p_total=p_total+LEAST(v_amount,p_cap);
 END LOOP;
 CLOSE c;
END$$
DELIMITER ;
CALL cursor_capped_total(50,@capped_total);
SELECT @capped_total AS capped_total;
